 for(const auto& a:actors)if(a.opponent){auto torso=child(h,a.id,"Torso"),primitive=rd<addr>(h,torso+Offsets::BasePart::Primitive);const auto group=rd<unsigned char>(h,primitive+ff3Play::physicsGroupOffset,255);if(group<32)bodies|=1u<<group;}
